def effective_gpu_qps(total_qps: int, l1_hit: float, l2_hit: float) -> int:
    if not (0.0 <= l1_hit + l2_hit <= 1.0):
        raise ValueError('Combined hit rate must be in [0, 1]')
    return int(round(total_qps * (1.0 - l1_hit - l2_hit)))

def estimate_l2_cluster_gb(num_entries: int, resp_bytes: int = 2048, dims: int = 384, m_links: int = 16) -> float:
    if num_entries <= 0:
        raise ValueError('num_entries must be positive')
    data_bytes = num_entries * (resp_bytes + dims)
    graph_bytes = num_entries * m_links * 2 * 4
    return round((data_bytes + graph_bytes) / 1e9, 2)

import hashlib

def compute_rbac_scope(tenant_id: str, acl_groups: list[str]) -> str:
    if not tenant_id:
        raise ValueError('tenant_id cannot be empty')
    normalized = ','.join(sorted(set(acl_groups)))
    return f'{tenant_id}:{hashlib.sha256(normalized.encode()).hexdigest()[:16]}'

def should_bypass_l2(l2_p99_ms: float, slo_cap_ms: float = 20.0) -> bool:
    if l2_p99_ms < 0:
        raise ValueError('Latency must be non-negative')
    return l2_p99_ms > slo_cap_ms

def pick_replica_with_bound(ring_candidates: list[int], loads: dict[int, float], avg_load: float, bound: float = 1.25) -> int:
    for rep in ring_candidates:
        if loads.get(rep, 0.0) <= avg_load * bound:
            return rep
    return min(ring_candidates, key=lambda r: loads.get(r, 0.0))

def kv_restore_ms(prefix_kv_mb: float, pcie_gbps: float = 32.0) -> float:
    if prefix_kv_mb < 0 or pcie_gbps <= 0:
        raise ValueError('Size and bandwidth must be positive')
    return round((prefix_kv_mb / (pcie_gbps * 1024.0)) * 1000.0, 2)

def shadow_audit_needed(request_hash_int: int, sample_pct: int = 1) -> bool:
    if not (0 <= sample_pct <= 100):
        raise ValueError('sample_pct must be in [0, 100]')
    return (request_hash_int % 100) < sample_pct
